import sys
import ast
import re

def two_sum(nums, target):
    # Write your solution here
    pass

def _parse_input(text):
    text = text.strip()
    if not text:
        return []
    if '=' in text:
        parts = re.split(r'(?:,\s*|[\r\n]+)(?=[a-zA-Z_][a-zA-Z0-9_]*\s*=)', text)
        args = []
        for p in parts:
            if '=' in p:
                _, val = p.split('=', 1)
                val = val.strip()
                val = re.sub(r'\bnull\b', 'None', val)
                val = re.sub(r'\btrue\b', 'True', val)
                val = re.sub(r'\bfalse\b', 'False', val)
                try:
                    args.append(ast.literal_eval(val))
                except Exception:
                    args.append(val)
            else:
                args.append(p.strip())
        return args
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    args = []
    for l in lines:
        l_clean = re.sub(r'\bnull\b', 'None', l)
        l_clean = re.sub(r'\btrue\b', 'True', l_clean)
        l_clean = re.sub(r'\bfalse\b', 'False', l_clean)
        try:
            args.append(ast.literal_eval(l_clean))
        except Exception:
            args.append(l.strip())
    return args

if __name__ == '__main__':
    input_data = sys.stdin.read().strip()
    args = _parse_input(input_data)
    try:
        result = two_sum(*args)
    except TypeError:
        result = two_sum()
    if result is not None:
        print(result)

